mapper.select:
SELECT 
  FROM device_desired_shadow_request
 WHERE requested_by = #{requestedBy} AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE device_desired_shadow_current
   SET desired_version = #{current.desiredVersion}, request_id = #{current.requestId},
       desired_state = CAST(#{current.desiredStateJson} AS jsonb),
       updated_at = #{current.updatedAt}
 WHERE device_id = #{current.deviceId} AND desired_version = #{expectedVersion}

UPDATE device_desired_shadow_request
   SET status = #{request.status}, failure_code = #{request.failureCode},
       applied_at = #{request.appliedAt}, status_updated_at = #{request.statusUpdatedAt},
       projection_version = #{request.projectionVersion}
 WHERE request_id = #{request.requestId}
   AND projection_version = #{expectedProjectionVersion}
